label_replace(((((((100 * sum by (instance) (
  oie_host_cpu_active_vcpus{job="openstack-instance-exporter", instance=~"^${gvar_oie_hypervisor}(:[0-9]+)?$"}
)
/
sum by (instance) (
  oie_host_cpu_threads{job="openstack-instance-exporter", instance=~"^${gvar_oie_hypervisor}(:[0-9]+)?$"}
