  unless on(instance) count by (instance) (oie_instance_inventory_info{job="openstack-instance-exporter", instance=~"^${gvar_oie_hypervisor}(:[0-9]+)?$", libvirt_active="1"})) and on(instance) (oie_host_cpu_threads{job="openstack-instance-exporter", instance=~"^${gvar_oie_hypervisor}(:[0-9]+)?$"} > 0)))
