  (up{job="openstack-instance-exporter", instance=~"^${gvar_oie_hypervisor}(:[0-9]+)?$"} == 1)
  and on(job, instance) (oie_host_libvirt_ok{job="openstack-instance-exporter", instance=~"^${gvar_oie_hypervisor}(:[0-9]+)?$"} == 1)
